-- WP19 tests written before migration; isolated fixture data rolls back.
begin;
create temporary table wp19_ids(label text primary key,id uuid);
create temporary table wp19_results(name text,passed boolean);
grant select,insert,update on wp19_ids,wp19_results to authenticated;
create function pg_temp.ai_id(label text) returns uuid language sql security invoker as $$select id from pg_temp.wp19_ids where wp19_ids.label=$1$$;
create function pg_temp.ai_check(name text,passed boolean) returns void language sql security invoker as $$insert into pg_temp.wp19_results values(name,coalesce(passed,false))$$;
create function pg_temp.ai_error(name text,query text,expected text) returns void language plpgsql security invoker as $$declare caught text;begin begin execute query;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.ai_check(name,caught=expected);end;$$;
insert into auth.users(id,email) values('19000000-0000-4000-8000-000000000001','wp19-rollback-a@example.invalid'),('19000000-0000-4000-8000-000000000002','wp19-rollback-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp19_ids values('a',public.create_wedding('WP19 AI synthetic','Test city'));
select public.save_draft_setup(pg_temp.ai_id('a'),(select state_version from public.weddings),'WP19 AI synthetic','Test city',null,true,null,'[{"title":"Reception"}]');
select public.generate_draft(pg_temp.ai_id('a'),(select state_version from public.weddings));
insert into wp19_ids select 'ceremony',id from public.ceremonies where wedding_id=pg_temp.ai_id('a');
insert into wp19_ids select 'request',(public.ai_reserve(pg_temp.ai_id('a'),array[pg_temp.ai_id('ceremony')])->>'request_id')::uuid;
select pg_temp.ai_check('first per-user reservation persisted',pg_temp.ai_id('request') is not null);
select pg_temp.ai_error('burst cannot bypass shared persistent rate limit',$$select public.ai_reserve(pg_temp.ai_id('a'),array[pg_temp.ai_id('ceremony')])$$,'PT429');
select pg_temp.ai_error('forged raw task identity denied',$$select public.ai_task_decision(pg_temp.ai_id('a'),'19000000-0000-4000-8000-000000000099','accept','Review a wet-weather plan',null)$$,'42501');
select pg_temp.ai_check('existing title normalized/case/punctuation excluded',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','CHOOSE invitation wording!',null)->>'status'='EXCLUDED');
select pg_temp.ai_check('ceremony-prefixed title excluded',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Draft a simple running order',null)->>'status'='EXCLUDED');
insert into wp19_ids select 'accepted',(public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Review a wet-weather plan',pg_temp.ai_id('ceremony'))->>'task_id')::uuid;
select pg_temp.ai_check('accepted task has only safe defaults',exists(select 1 from public.tasks where id=pg_temp.ai_id('accepted') and status='TO_DO' and due_date is null and owner_name is null and description is null and prerequisite_task_id is null and completed_at is null and ceremony_id=pg_temp.ai_id('ceremony')));
select pg_temp.ai_check('double submission returns same task',(public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Review a wet-weather plan',pg_temp.ai_id('ceremony'))->>'task_id')=pg_temp.ai_id('accepted')::text);
select pg_temp.ai_check('only one task created',(select count(*) from public.tasks where wedding_id=pg_temp.ai_id('a') and title='Review a wet-weather plan')=1);
select pg_temp.ai_check('only one acceptance audit',(select count(*) from public.audit_events where entity_id=pg_temp.ai_id('accepted') and action='OPTIONAL_SUGGESTION_ACCEPTED')=1);
select pg_temp.ai_check('dismissal retained',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'dismiss','Review reusable containers',null)->>'status'='DISMISSED');
select pg_temp.ai_check('dismissed candidate cannot be reaccepted',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','review reusable containers!',null)->>'status'='DISMISSED');
select pg_temp.ai_check('dismissal replay idempotent',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'dismiss','Review reusable containers',null)->>'status'='DISMISSED');
reset role;
insert into wedding_private.tasks(wedding_id,title,status,completed_at) values(pg_temp.ai_id('a'),'Completed optional preparation','COMPLETED',clock_timestamp());
set local role authenticated;
select pg_temp.ai_check('completed title excluded',public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','completed optional preparation!',null)->>'status'='EXCLUDED');
select pg_temp.ai_error('ordinary users cannot reset usage',$$delete from wedding_private.ai_request_slots where wedding_id=pg_temp.ai_id('a')$$,'42501');
select pg_temp.ai_error('ordinary users cannot rewrite dismissals',$$update wedding_private.ai_dismissed_titles set title='Forged' where wedding_id=pg_temp.ai_id('a')$$,'42501');
select pg_temp.ai_check('anon execute denied',not has_function_privilege('anon','public.ai_reserve(uuid,uuid[])','execute') and not has_function_privilege('anon','public.ai_task_decision(uuid,uuid,text,text,uuid)','execute'));
select set_config('request.jwt.claims','{"sub":"19000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into wp19_ids values('b',public.create_wedding('WP19 B synthetic','Test city'));
select public.save_draft_setup(pg_temp.ai_id('b'),(select state_version from public.weddings),'WP19 B synthetic','Test city',null,true,null,'[{"title":"Reception"}]');
select public.generate_draft(pg_temp.ai_id('b'),(select state_version from public.weddings));
insert into wp19_ids select 'bceremony',id from public.ceremonies where wedding_id=pg_temp.ai_id('b');
select pg_temp.ai_check('B has independent per-user allowance',public.ai_reserve(pg_temp.ai_id('b'),array[pg_temp.ai_id('bceremony')])->>'request_id' is not null);
select pg_temp.ai_error('B cannot reserve A context',$$select public.ai_reserve(pg_temp.ai_id('a'),array[pg_temp.ai_id('ceremony')])$$,'42501');
select pg_temp.ai_error('B cannot use A request',$$select public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Review backup seating',null)$$,'42501');
select set_config('request.jwt.claims','{"sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.ai_error('forged B ceremony denied',$$select public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Review backup seating',pg_temp.ai_id('bceremony'))$$,'23503');
select public.activate_plan(pg_temp.ai_id('a'),(select state_version from public.weddings where id=pg_temp.ai_id('a')),true);
select pg_temp.ai_error('AI cannot mutate ACTIVE plan',$$select public.ai_task_decision(pg_temp.ai_id('a'),pg_temp.ai_id('request'),'accept','Review extra supplies',null)$$,'55000');
select pg_temp.ai_error('ACTIVE model request denied',$$select public.ai_reserve(pg_temp.ai_id('a'),array[pg_temp.ai_id('ceremony')])$$,'55000');
reset role;
select jsonb_build_object('checks',jsonb_agg(jsonb_build_object('name',name,'passed',passed)),'total',count(*),'passed',count(*) filter(where passed),'failed',count(*) filter(where not passed)) as wp19_result from wp19_results;
rollback;
